settings.homeCss:
.site-builder-home .neco-lobby { display: flex; flex-direction: column; gap: 3rem; width: min(100%, 80rem); margin: 0 auto; padding: 2rem clamp(1rem, 4vw, 3rem) 4rem; box-sizing: border-box; }
.site-builder-home .neco-lobby__hero { position: relative; overflow: hidden; padding: clamp(2rem, 6vw, 4rem); text-align: center; }
.site-builder-home .neco-lobby__hero-bg { position: absolute; inset: 0; background-size: cover; background-position: center; image-rendering: pixelated; opacity: .35; pointer-events: none; }
.site-builder-home .neco-lobby__hero-inner { position: relative; display: flex; flex-direction: column; align-items: center; gap: 1.25rem; }
.site-builder-home .neco-lobby__logo { width: 96px; height: 96px; image-rendering: pixelated; }
.site-builder-home .neco-lobby__title { margin: 0; font-size: clamp(1.6rem, 4vw, 2.6rem); }
.site-builder-home .neco-lobby__tagline { margin: 0; max-width: 40rem; line-height: 1.9; opacity: .85; white-space: pre-line; }
.site-builder-home .neco-lobby__welcome { letter-spacing: 1px; opacity: .9; }
.site-builder-home .neco-lobby__hero-actions { display: flex; flex-wrap: wrap; gap: 1rem; justify-content: center; align-items: center; }
.site-builder-home .neco-lobby__btn { display: inline-block; padding: .6rem 1.6rem; border: 2px solid currentColor; text-decoration: none; letter-spacing: 1px; color: inherit; }
.site-builder-home .neco-lobby__btn--primary { font-weight: 700; }
.site-builder-home .neco-lobby__section-title { text-align: center; margin: 0 0 1.5rem; }
.site-builder-home .neco-lobby__intro-list { display: flex; flex-direction: column; gap: 1.5rem; }
.site-builder-home .neco-lobby__intro-card { display: flex; gap: 1.25rem; align-items: stretch; padding: 1rem 1.25rem; max-width: 44rem; animation: neco-fade-in-left .5s ease both; }
.site-builder-home .neco-lobby__intro-list > .neco-lobby__intro-card:nth-child(even) { align-self: flex-end; flex-direction: row-reverse; animation: neco-fade-in-right .5s ease both; }
.site-builder-home .neco-lobby__intro-media { width: 10rem; min-height: 7rem; flex: none; background-size: cover; background-position: center; image-rendering: pixelated; border: 2px solid var(--yb-site-border); }
.site-builder-home .neco-lobby__intro-media[data-has-image=""] { display: none; }
.site-builder-home .neco-lobby__intro-body h3 { margin: .25rem 0 .5rem; }
.site-builder-home .neco-lobby__intro-body p { margin: 0; line-height: 1.9; }
.site-builder-home .neco-lobby__server-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr)); gap: 1.5rem; }
.site-builder-home .neco-server { padding: 1rem 1.25rem; display: flex; flex-direction: column; gap: .5rem; }
.site-builder-home .neco-server__head { display: flex; align-items: center; gap: .6rem; }
.site-builder-home .neco-server__head h3 { margin: 0; flex: 1; }
.site-builder-home .neco-server__icon { width: 2rem; height: 2rem; flex: none; background-size: cover; image-rendering: pixelated; border: 2px solid var(--yb-site-border); }
.site-builder-home .neco-server__icon[data-icon=""] { display: none; }
.site-builder-home .neco-server__badge { font-size: .8em; padding: .1rem .5rem; border: 2px solid currentColor; }
.site-builder-home .neco-server__badge--true { color: var(--yb-site-primary); }
.site-builder-home .neco-server__badge--false { color: var(--yb-site-danger); }
.site-builder-home .neco-server__motd { margin: 0; line-height: 1.8; flex: 1; }
.site-builder-home .neco-server__meta { margin: 0; font-size: .85em; opacity: .7; word-break: break-all; }
.site-builder-home .neco-lobby__cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); gap: 1.5rem; }
.site-builder-home .neco-lobby__card { padding: .25rem 1rem .75rem; display: flex; flex-direction: column; gap: .5rem; }
.site-builder-home .neco-lobby__card-title { margin: .5rem 0 0; }
.site-builder-home .neco-lobby__card-title a { color: inherit; text-decoration: none; }
.site-builder-home .neco-lobby__card-excerpt { margin: 0; line-height: 1.8; flex: 1; }
.site-builder-home .neco-lobby__card-date { font-size: .85em; opacity: .65; }
.site-builder-home .neco-lobby__empty { text-align: center; opacity: .7; }
.site-builder-home .neco-lobby__cta { padding: clamp(1.5rem, 4vw, 3rem); text-align: center; }
.site-builder-home .neco-lobby__cta h2 { margin-top: 0; }
.site-builder-home .neco-lobby__cta p { opacity: .85; }
@media (max-width: 640px) { .site-builder-home .neco-lobby__intro-card, .site-builder-home .neco-lobby__intro-list > .neco-lobby__intro-card:nth-child(even) { flex-direction: column; align-self: stretch; } .site-builder-home .neco-lobby__intro-media { width: 100%; } }

pages.cssContent:
.neco-servers { width: min(100%, 80rem); margin: 0 auto; padding: 2rem clamp(1rem, 4vw, 3rem) 4rem; display: flex; flex-direction: column; gap: 2.5rem; box-sizing: border-box; }
.neco-servers__header { text-align: center; }
.neco-servers__header h1 { margin-bottom: .5rem; }
.neco-servers__subtitle { opacity: .75; margin: 0; }
.neco-servers__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(17rem, 1fr)); gap: 1.5rem; }
.neco-server-card { padding: 1rem 1.25rem; display: flex; flex-direction: column; gap: .5rem; }
.neco-server-card__head { display: flex; align-items: center; gap: .6rem; }
.neco-server-card__head h2 { margin: 0; flex: 1; font-size: 1.15rem; }
.neco-server-card__icon { width: 2.25rem; height: 2.25rem; flex: none; background-size: cover; image-rendering: pixelated; border: 2px solid var(--yb-site-border); }
.neco-server-card__icon[data-icon=""] { display: none; }
.neco-server-card__badge { font-size: .8em; padding: .1rem .5rem; border: 2px solid currentColor; }
.neco-server-card__badge--true { color: var(--yb-site-primary); }
.neco-server-card__badge--false { color: var(--yb-site-danger); }
.neco-server-card__motd { margin: 0; line-height: 1.8; }
.neco-server-card__desc { margin: 0; line-height: 1.8; opacity: .85; flex: 1; }
.neco-server-card__meta { margin: 0; font-size: .85em; opacity: .7; word-break: break-all; }
.neco-servers__empty { text-align: center; opacity: .7; }
.neco-servers__section-title { text-align: center; margin: 0 0 1.5rem; }
.neco-servers__dept-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); gap: 1.5rem; }
.neco-servers__dept { padding: .25rem 1rem .75rem; }
.neco-servers__dept p { margin: 0; line-height: 1.9; }
.neco-servers__link-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr)); gap: 1rem; }
.neco-servers__link { display: flex; align-items: center; gap: .6rem; padding: .75rem 1rem; color: inherit; text-decoration: none; }
.neco-servers__link-icon { width: 1.75rem; height: 1.75rem; flex: none; background-size: cover; image-rendering: pixelated; }
.neco-servers__link-icon[data-icon=""] { display: none; }

.neco-news { width: min(100%, 64rem); margin: 0 auto; padding: 2rem clamp(1rem, 4vw, 3rem) 4rem; display: flex; flex-direction: column; gap: 2rem; box-sizing: border-box; }
.neco-news__header { text-align: center; }
.neco-news__header h1 { margin-bottom: .5rem; }
.neco-news__subtitle { opacity: .75; margin: 0; }
.neco-news__list { display: flex; flex-direction: column; gap: 1.25rem; }
.neco-news__item { padding: .5rem 1.25rem .85rem; display: flex; flex-direction: column; gap: .4rem; }
.neco-news__item-title { margin: .5rem 0 0; font-size: 1.1rem; }
.neco-news__item-title a { color: inherit; text-decoration: none; }
.neco-news__item-excerpt { margin: 0; line-height: 1.8; }
.neco-news__item-date { font-size: .85em; opacity: .65; }
.neco-news__empty { text-align: center; opacity: .7; }

.neco-activity { width: min(100%, 80rem); margin: 0 auto; padding: 2rem clamp(1rem, 4vw, 3rem) 4rem; display: flex; flex-direction: column; gap: 2rem; box-sizing: border-box; }
.neco-activity__header { text-align: center; }
.neco-activity__header h1 { margin-bottom: .5rem; }
.neco-activity__subtitle { opacity: .75; margin: 0; }
.neco-activity__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(17rem, 1fr)); gap: 1.5rem; }
.neco-activity__card { padding: .5rem 1.25rem .85rem; display: flex; flex-direction: column; gap: .4rem; }
.neco-activity__card-head { display: flex; align-items: center; gap: .6rem; }
.neco-activity__card-head h2 { margin: .5rem 0 0; flex: 1; font-size: 1.1rem; }
.neco-activity__card-head a { color: inherit; text-decoration: none; }
.neco-activity__status { font-size: .8em; padding: .1rem .5rem; border: 2px solid currentColor; }
.neco-activity__status--ongoing { color: var(--yb-site-primary); }
.neco-activity__status--upcoming { color: var(--yb-site-caption); }
.neco-activity__status--ended { color: var(--yb-site-danger); }
.neco-activity__card-meta { margin: 0; font-size: .85em; opacity: .7; }
.neco-activity__card-summary { margin: 0; line-height: 1.8; }
.neco-activity__empty { text-align: center; opacity: .7; }

.neco-about { width: min(100%, 72rem); margin: 0 auto; padding: 2rem clamp(1rem, 4vw, 3rem) 4rem; display: flex; flex-direction: column; gap: 2.5rem; box-sizing: border-box; }
.neco-about__header { text-align: center; }
.neco-about__header h1 { margin-bottom: .5rem; }
.neco-about__subtitle { opacity: .75; margin: 0; }
.neco-about__intro-list { display: flex; flex-direction: column; gap: 1.5rem; }
.neco-about__card { max-width: 34rem; padding: .5rem 1rem .75rem; animation: neco-fade-in-left .5s ease both; }
.neco-about__intro-list > .neco-about__card:nth-child(even) { align-self: flex-end; animation: neco-fade-in-right .5s ease both; }
.neco-about__media { height: 8rem; margin: .5rem 0 0; background-size: cover; background-position: center; image-rendering: pixelated; border: 2px solid var(--yb-site-border); }
.neco-about__media[data-has-image=""] { display: none; }
.neco-about__card h2 { margin-top: .75rem; }
.neco-about__card p { line-height: 1.9; }
